const GO_LIVE = '2026-09-05';   // date the automations went live (for before/after charts)

const BIZ = {
  realty: { name: 'Palm & Co Realty',    tag: 'Real estate' },
  store:  { name: 'Oasis Home Store',    tag: 'Online store' },
  agency: { name: 'Pixel Bridge Agency', tag: 'Services' },
};

// ---- read the sheets (node names must match exactly) ------------------------
const read = (name) => $(name).all().map((i) => i.json).filter((r) => Object.values(r).some((v) => String(v).trim() !== ''));
const tx      = read('Get transactions');
const leads   = read('Get leads');
const cash    = read('Get cashflow');
const team    = read('Get team');
const tickets = read('Get tickets');
const ledger  = read('Get ledger');
const stock   = read('Get inventory');
const procs   = read('Get processes');

// ---- helpers ----------------------------------------------------------------
const num = (v) => Number(String(v ?? '').replace(/,/g, '')) || 0;
const iso = (v) => {
  const s = String(v ?? '').trim().slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    throw new Error('Date "' + v + '" is not in YYYY-MM-DD format. Re-import the sheet with "Convert text to numbers, dates and formulas" switched OFF (GUIDE.md, step 1.3).');
  }
  return s;
};
const addDays = (d, n) => {
  const t = new Date(d + 'T00:00:00Z');
  t.setUTCDate(t.getUTCDate() + n);
  return t.toISOString().slice(0, 10);
};
const sum = (a) => a.reduce((s, x) => s + x, 0);
const avg = (a) => (a.length ? sum(a) / a.length : 0);
const r0 = (x) => Math.round(x);
const r1 = (x) => Math.round(x * 10) / 10;
const r2 = (x) => Math.round(x * 100) / 100;
const pct = (cur, prev) => (prev ? r1(((cur - prev) / prev) * 100) : null);
const countBy = (rows, key) => {
  const m = {};
  rows.forEach((r) => { m[r[key]] = (m[r[key]] || 0) + 1; });
  return m;
};
const topN = (obj, n) => Object.entries(obj).sort((a, b) => b[1] - a[1]).slice(0, n).map(([k, v]) => ({ name: k, value: v }));

// normalise types once
tx.forEach((r) => { r.date = iso(r.date); r.amount = num(r.amount_aed); });
leads.forEach((r) => { r.date = iso(r.date); r.fr = num(r.first_response_min); });
cash.forEach((r) => { r.date = iso(r.date); r.amount = num(r.amount_aed); });
team.forEach((r) => { r.week = iso(r.week_start); });
tickets.forEach((r) => { r.date = iso(r.date); r.sec = num(r.response_sec); });
ledger.forEach((r) => { r.date = iso(r.date); r.mins = num(r.minutes_saved); });

// ---- time windows (anchored to the latest data date, so the dashboard never goes empty) ----
const ref = tx.map((r) => r.date).sort().pop();
const curFrom = addDays(ref, -29), prevFrom = addDays(ref, -59), prevTo = addDays(ref, -30);
const inCur = (d) => d >= curFrom && d <= ref;
const inPrev = (d) => d >= prevFrom && d <= prevTo;
const curDays = Array.from({ length: 30 }, (_, i) => addDays(curFrom, i));
const weekStarts = Array.from({ length: 8 }, (_, i) => addDays(ref, -7 * (8 - i) + 1)); // 8 rolling weeks
const weekOf = (d) => {
  for (let i = weekStarts.length - 1; i >= 0; i--) if (d >= weekStarts[i]) return i;
  return -1;
};

// ---- per-business block -----------------------------------------------------
function business(key) {
  const done = tx.filter((r) => r.business === key && r.status === 'completed');
  const revCur = sum(done.filter((r) => inCur(r.date)).map((r) => r.amount));
  const revPrev = sum(done.filter((r) => inPrev(r.date)).map((r) => r.amount));
  const ordersCur = done.filter((r) => inCur(r.date)).length;
  const ordersPrev = done.filter((r) => inPrev(r.date)).length;
  const daily = curDays.map((d) => r0(sum(done.filter((r) => r.date === d).map((r) => r.amount))));

  const L = leads.filter((r) => r.business === key && inCur(r.date));
  const Lprev = leads.filter((r) => r.business === key && inPrev(r.date));
  const won = L.filter((r) => r.status === 'won').length;

  const C = cash.filter((r) => r.business === key);
  const income = sum(C.filter((r) => r.type === 'income' && inCur(r.date)).map((r) => r.amount));
  const expense = sum(C.filter((r) => r.type === 'expense' && inCur(r.date)).map((r) => r.amount));
  const weekly = weekStarts.map(() => ({ income: 0, expense: 0 }));
  C.forEach((r) => {
    const w = weekOf(r.date);
    if (w >= 0 && r.date <= ref) weekly[w][r.type] += r.amount;
  });
  const expByCat = {};
  C.filter((r) => r.type === 'expense' && inCur(r.date)).forEach((r) => {
    expByCat[r.category] = (expByCat[r.category] || 0) + r.amount;
  });

  const teamFrom = addDays(ref, -28);
  const T = team.filter((r) => r.business === key && r.week >= teamFrom);
  const people = [...new Set(T.map((r) => r.employee))].map((name) => {
    const rows = T.filter((r) => r.employee === name);
    return {
      name,
      tasks: r0(sum(rows.map((r) => num(r.tasks_completed)))),
      response_min: r1(avg(rows.map((r) => num(r.avg_response_min)))),
      csat: r2(avg(rows.map((r) => num(r.csat)))),
    };
  }).sort((a, b) => b.tasks - a.tasks);

  const TK = tickets.filter((r) => r.business === key && inCur(r.date));
  const agentTk = TK.filter((r) => r.handled_by === 'agent');
  const humanTk = TK.filter((r) => r.handled_by === 'human');

  const out = {
    name: BIZ[key].name,
    tag: BIZ[key].tag,
    kpis: {
      revenue: r0(revCur), revenue_change_pct: pct(revCur, revPrev),
      orders: ordersCur, orders_change_pct: pct(ordersCur, ordersPrev),
      avg_order_value: ordersCur ? r0(revCur / ordersCur) : 0,
      leads: L.length, leads_change_pct: pct(L.length, Lprev.length),
      conversion_pct: L.length ? r1((won / L.length) * 100) : 0,
      first_response_min: r1(avg(L.map((r) => r.fr))),
      net_cash: r0(income - expense), income: r0(income), expense: r0(expense),
    },
    daily_revenue: daily,
    cash_weekly: weekStarts.map((w, i) => ({ week: w, income: r0(weekly[i].income), expense: r0(weekly[i].expense) })),
    expense_by_category: topN(expByCat, 6).map((x) => ({ name: x.name, value: r0(x.value) })),
    leads_by_score: ['Hot', 'Warm', 'Cold'].map((s) => ({ name: s, value: L.filter((r) => r.score === s).length })),
    leads_by_source: topN(countBy(L, 'source'), 5),
    leads_by_status: topN(countBy(L, 'status'), 5),
    team: people,
    tickets: {
      total: TK.length,
      agent_share_pct: TK.length ? r1((agentTk.length / TK.length) * 100) : 0,
      agent_response_sec: r1(avg(agentTk.map((r) => r.sec))),
      human_response_sec: r0(avg(humanTk.map((r) => r.sec))),
    },
  };
  if (key === 'store') {
    out.low_stock = stock
      .map((r) => ({ sku: r.sku, product: r.product, stock: num(r.stock), reorder_level: num(r.reorder_level) }))
      .filter((r) => r.stock <= r.reorder_level)
      .sort((a, b) => (a.stock - a.reorder_level) - (b.stock - b.reorder_level))
      .slice(0, 6);
  }
  return out;
}

const businesses = {};
Object.keys(BIZ).forEach((k) => { businesses[k] = business(k); });

// ---- group block ------------------------------------------------------------
const keys = Object.keys(BIZ);
const gRev = sum(keys.map((k) => businesses[k].kpis.revenue));
const gPrev = sum(keys.map((k) => sum(tx.filter((r) => r.business === k && r.status === 'completed' && inPrev(r.date)).map((r) => r.amount))));
const gOrders = sum(keys.map((k) => businesses[k].kpis.orders));
const gLeads = sum(keys.map((k) => businesses[k].kpis.leads));
const gNet = sum(keys.map((k) => businesses[k].kpis.net_cash));
const allLeadsCur = leads.filter((r) => inCur(r.date));

// first-response trend: rolling weeks over the last 13 weeks
const trendWeeks = Array.from({ length: 13 }, (_, i) => addDays(ref, -7 * (13 - i) + 1));
const frTrend = trendWeeks.map((w, i) => {
  const end = i === 12 ? ref : addDays(trendWeeks[i + 1], -1);
  const rows = leads.filter((r) => r.date >= w && r.date <= end);
  return { week: w, minutes: r1(avg(rows.map((r) => r.fr))) };
});
const before = leads.filter((r) => r.date < GO_LIVE);
const after = leads.filter((r) => r.date >= GO_LIVE);
const tkBefore = tickets.filter((r) => r.date < GO_LIVE && r.handled_by === 'human');
const tkAfterHuman = tickets.filter((r) => r.date >= GO_LIVE && r.handled_by === 'human');
const tkAfterAgent = tickets.filter((r) => r.date >= GO_LIVE && r.handled_by === 'agent');
const tkCur = tickets.filter((r) => inCur(r.date));

// ledger: hours saved
const hoursBy = {};
ledger.forEach((r) => { hoursBy[r.workflow] = (hoursBy[r.workflow] || 0) + r.mins / 60; });
const hoursWeekly = weekStarts.map(() => 0);
ledger.forEach((r) => { const w = weekOf(r.date); if (w >= 0 && r.date <= ref) hoursWeekly[w] += r.mins / 60; });

// process register
const P = procs.map((r) => ({
  id: r.process_id, business: r.business, process: r.process,
  manual_hours: r1(num(r.manual_hours_per_month)),
  saveable_hours: r1(num(r.hours_saveable_per_month)),
  feasibility: num(r.automation_feasibility), status: r.status, automated_by: r.automated_by || '',
}));
const live = P.filter((p) => p.status === 'Live');

const kpis = {
  generated_at: new Date().toISOString(),
  ref_date: ref,
  window: { from: curFrom, to: ref, days: 30 },
  go_live: GO_LIVE,
  data_note: 'Synthetic demo data',
  group: {
    kpis: {
      revenue: gRev, revenue_change_pct: pct(gRev, gPrev),
      orders: gOrders, leads: gLeads, net_cash: gNet,
      first_response_min: r1(avg(allLeadsCur.map((r) => r.fr))),
    },
    daily_revenue: curDays.map((d, i) => ({ date: d, realty: businesses.realty.daily_revenue[i], store: businesses.store.daily_revenue[i], agency: businesses.agency.daily_revenue[i] })),
    revenue_share: keys.map((k) => ({ key: k, name: BIZ[k].name, value: businesses[k].kpis.revenue })),
    net_cash_by_business: keys.map((k) => ({ key: k, name: BIZ[k].name, value: businesses[k].kpis.net_cash })),
    automation: {
      hours_saved_30d: r0(sum(ledger.filter((r) => inCur(r.date)).map((r) => r.mins)) / 60),
      hours_saved_total: r0(sum(ledger.map((r) => r.mins)) / 60),
      runs_total: ledger.length,
      hours_by_workflow: Object.entries(hoursBy).sort((a, b) => b[1] - a[1]).map(([w, h]) => ({ name: w, value: r1(h) })),
      hours_weekly: weekStarts.map((w, i) => ({ week: w, hours: r1(hoursWeekly[i]) })),
      first_response_trend: frTrend,
      first_response_before_min: r1(avg(before.map((r) => r.fr))),
      first_response_after_min: r1(avg(after.map((r) => r.fr))),
      tickets_30d: tkCur.length,
      agent_share_pct: tkCur.length ? r1((tkCur.filter((r) => r.handled_by === 'agent').length / tkCur.length) * 100) : 0,
      human_response_before_sec: r0(avg(tkBefore.map((r) => r.sec))),
      human_response_after_sec: r0(avg(tkAfterHuman.map((r) => r.sec))),
      agent_response_sec: r1(avg(tkAfterAgent.map((r) => r.sec))),
      processes_live: live.length,
      processes_total: P.length,
      register_hours_saved_live: r0(sum(live.map((p) => p.saveable_hours))),
      register_hours_open: r0(sum(P.filter((p) => p.status !== 'Live').map((p) => p.saveable_hours))),
      top_processes: [...P].sort((a, b) => b.saveable_hours - a.saveable_hours).slice(0, 7),
    },
  },
  businesses,
};

return [{ json: kpis }];
